import type { ProjectTemplate } from '@/entities/project/types'
import { Badge } from './Badge'
import { Eye, Copy } from 'lucide-react'

type Props = {
  template: ProjectTemplate
  onPreview: () => void
  onUse: () => void
}

export function TemplateCard({ template, onPreview, onUse }: Props) {
  return (
    <div className="bg-surface rounded-xl border border-border p-5 flex flex-col gap-3">
      <div>
        <div className="flex items-start justify-between mb-1">
          <h3 className="font-semibold text-sm">{template.title}</h3>
          <Badge variant={template.type === 'public' ? 'success' : template.type === 'paid' ? 'warning' : 'outline'}>
            {template.type}
          </Badge>
        </div>
        <p className="text-xs text-muted-foreground">{template.description}</p>
      </div>
      <div className="flex flex-wrap gap-1">
        {template.tags.map((tag) => (
          <span key={tag} className="px-1.5 py-0.5 bg-muted rounded text-xs">{tag}</span>
        ))}
      </div>
      <p className="text-xs text-muted-foreground">{template.objectivesCount} objectives</p>
      <div className="flex gap-2 mt-auto">
        <button onClick={onPreview} className="flex items-center gap-1 text-xs border border-border px-3 py-1.5 rounded-lg text-muted-foreground hover:text-foreground">
          <Eye size={12} /> Preview
        </button>
        <button onClick={onUse} className="flex-1 flex items-center justify-center gap-1 text-xs bg-accent text-accent-foreground py-1.5 rounded-lg hover:opacity-90">
          <Copy size={12} /> Use template
        </button>
      </div>
    </div>
  )
}
